pe":"object"},"name":"generate_password","readOnlyHint":true},{"description":"Get metadata for a vault entry. Returns type, usage hints, and field names without secret values. Use get_entry_value to retrieve actual values.","inputSchema":{"properties":{"path":{"description":"Entry path","type":"string"}},"required":["path"],"type":"object"},"name":"get_entry","readOnlyHint":true},{"description":"Get metadata for a vault entry without retrieving sensitive data","inputSchema":{"properties":{"path":{"description":"Entry path","type":"string"}},"required":["path"],"type":"object"},"name":"get_entry_metadata","readOnlyHint":true},{"description":"Return Symaira Vault MCP server health information","inputSchema":{"properties":{},"type":"object"},"name":"health","readOnlyHint":true},{"description":"List vault entries matching a prefix with metadata","inputSchema":{"properties":{"include_details":{"description":"When true, returns metadata for each entry. Default: false to avoid expensive decryption on large vaults.","type":"boolean"},"prefix":{"description":"Path prefix to filter","type":"string"}},"type":"object"},"name":"list_entries","readOnlyHint":true},{"description":"Search the web using Perplexity AI. Returns synthesized search results with citations from the web.","inputSchema":{"properties":{"query":{"description":"Natural language search query","type":"string"}},"required":["query"],"type":"object"},"name":"perplexity_search","readOnlyHint":true},{"description":"Ask Perplexity AI a question with optional vault entry context. Returns an AI-generated answer with citations.","inputSchema":{"properties":{"context":{"description":"Optional context from vault entries to include in the question","type":"string"},"question":{"description":"Question to ask Perplexity AI","type":"string"}},"required":["question"],"type":"object"},"name":"perplexity_ask","readOnlyHint":true},{"description":"Execute a command on the host with secrets injected as environment variables. Requires write permission.","destructiveHint":true,"inputSchema":{"properties":{"command":{"description":"\"Command and arguments as an array (e.g. [\"curl\", \"https://api.example.com\"])","type":"array"},"env":{"description":"\"Map of environment variable names to secret references (e.g. {\"API_KEY\": \"github.api_key\"})","type":"object"},"files":{"description":"Map of safe file names to secret references or {ref, encoding: base64} objects. Files are materialized ephemerally and exposed as SYMVAULT_FILE_\u003cname\u003e paths.","type":"object"},"timeout":{"description":"Timeout in seconds (default: 30)","type":"number"},"working_dir":{"description":"Working directory for the command","type":"string"}},"required":["command"],"type":"object"},"name":"run_command"},{"description":"Scan text for secrets and replace them with masked values. Use before sending output to LLM chat.","inputSchema":{"properties":{"mask":{"description":"Custom mask string (default: ***)","type":"string"},"mask_with_op_refs":{"description":"Replace vault-known secrets with op:// references","type":"boolean"},"text":{"description":"Text to scan for secrets","type":"string"}},"required":["text"],"type":"object"},"name":"sanitize_output","readOnlyHint":true},{"description":"Discover tools by intent matching. Returns tools whose name or description matches the intent.","inputSchema":{"properties":{"intent":{"description":"Natural language intent or keyword to search for","type":"string"},"return":{"description":"Output format: \"spec\" (full tool specs) or \"names\" (just tool names). Default: \"spec\".","type":"string"}},"required":["intent"],"type":"object"},"name":"symaira_search","readOnlyHint":true},{"description":"Search vault entries by query. Returns results with id, title, and url for each matching entry.","inputSchema":{"properties":{"query":{"description":"Search query to match against entry paths and field values","type":"string"}},"required":["query"],"type":"object"},"name":"search","readOnlyHint":true},{"description":"Fetch a vault entry by path/id. Returns the full entry content with metadata and values.","inputSchema":{"properties":{"id":{"description":"Entry path or id to fetch (e.g., 'github' or 'work/aws')","type":"string"}},"required":["id"],"type":"object"},"name":"fetch","readOnlyHint":true},{"description":"Set a field on an entry (requires write scope)","destructiveHint":true,"inputSchema":{"properties":{"field":{"description":"Field name","type":"string"},"force":{"description":"Skip password strength validation. Default: false.","type":"boolean"},"path":{"description":"Entry path","type":"string"},"value":{"description":"Field value","type":"string"}},"required":["path","field","value"],"type":"object"},"name":"set_entry_field"},{"description":"Request to share a secret with another agent. Creates a pending share grant that requires human approval.","destructiveHint":true,"inputSchema":{"properties":{"secret_field":{"description":"Specific field to share (optional, shares entire entry if omitted)","type":"string"},"secret_path":{"description":"Path to the secret entry (e.g., \"api-keys/stripe\")","type":"string"},"to_agent":{"description":"Name of the agent to share the secret with","type":"string"},"ttl":{"description":"Time-to-live duration (e.g., \"1h\", \"30m\"). Share expires after this duration.","type":"string"}},"required":["to_agent","secret_path"],"type":"object"},"name":"request_share"},{"description":"Approve a pending share request. Requires human confirmation.","destructiveHint":true,"inputSchema":{"properties":{"grant_id":{"description":"ID of the share grant to approve","type":"string"}},"required":["grant_id"],"type":"object"},"name":"approve_share"},{"description":"Revoke an active share grant, immediately removing access.","destructiveHint":true,"inputSchema":{"properties":{"grant_id":{"description":"ID of the share grant to revoke","type":"string"}},"required":["grant_id"],"type":"object"},"name":"revoke_share"},{"description":"List share grants. Can filter by status, agent, or secret path.","inputSchema":{"properties":{"from_agent":{"description":"Filter by source agent name","type":"string"},"secret_path":{"description":"Filter by secret path","type":"string"},"status":{"description":"Filter by status: pending, approved, revoked, expired, rejected","type":"string"},"to_agent":{"description":"Filter by target agent name","type":"string"}},"type":"object"},"name":"list_shares","readOnlyHint":true},{"description":"Generate a configuration file from a template","inputSchema":{"properties":{"dry_run":{"description":"Show template with masked values. Default: false","type":"boolean"},"name":{"description":"Name of the resource being generated. Default: app","type":"string"},"output_path":{"description":"Output file path (optional)","type":"string"},"secret_refs":{"description":"Map of template variable names to vault references","type":"object"},"template_type":{"description":"Template type (env, docker-compose, k8s-secret, github-actions, terraform)","type":"string"}},"required":["template_type"],"type":"object"},"name":"generate_template","readOnlyHint":true},{"description":"Generate a TOTP code for an entry with TOTP configuration. By default the code is copied to the clipboard without being returned in the response. Use destination=\"autotype\" to type the code directly, or destination=\"return\" with return_code=true to return the code in the response (requires approval).","inputSchema":{"properties":{"destination":{"description":"Where to send the code: \"clipboard\" (default, not returned), \"autotype\" (type directly), \"return\" (return in response, requires approval)","type":"string"},"path":{"description":"Entry path with TOTP configuration","type":"string"},"return_code":{"description":"Must be true when destination=\"return\"","type":"boolean"}},"required":["path"],"type":"object"},"name":"generate_totp","readOnlyHint":true},{"description":"Unseal a secret handle to reveal its value. High-sensitivity entries return handles (op://path/field) instead of plaintext. This tool resolves those handles. Requires user approval per handle.","inputSchema":{"properties":{"handle":{"description":"Secret handle to unseal (e.g. op://github/password)","type":"string"}},"required":["handle"],"type":"object"},"name":"secret_unseal","readOnlyHint":true},{"description":"Return the agent profile, available/unavailable tools, quotas, and vault status","inputSchema":{"properties":{},"type":"object"},"name":"symaira_whoami","readOnlyHint":true}]}}
